WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant, account_id ORDER BY amount NULLS FIRST, id) AS row_num FROM transactions) ranked WHERE row_num = 1) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, SUM(amount) FILTER (WHERE txn_type = 'REFUND') AS refund_total_amount, STDDEV_SAMP(amount) AS amount_stddev, SIZE(COLLECT_SET(merchant)) AS num_merchants, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN txn_type = 'FEE' THEN 1 END), 0), 2) AS amount_per_fee, MAX(amount) FILTER (WHERE txn_type = 'REFUND') AS refund_max_amount FROM ranked GROUP BY ROLLUP (DATE_TRUNC('QUARTER', txn_time)) ORDER BY num_merchants DESC NULLS FIRST
